DWORD checked_dword(std::size_t value,const char*error){if(value>static_cast<std::size_t>((std::numeric_limits<DWORD>::max)()))throw std::runtime_error(error);return static_cast<DWORD>(value);}
ULONG checked_ulong(std::size_t value,const char*error){if(value>static_cast<std::size_t>((std::numeric_limits<ULONG>::max)()))throw std::runtime_error(error);return static_cast<ULONG>(value);}
USHORT checked_ushort_bytes(std::size_t characters,const char*error){if(characters>static_cast<std::size_t>((std::numeric_limits<USHORT>::max)())/sizeof(wchar_t))throw std::runtime_error(error);return static_cast<USHORT>(characters*sizeof(wchar_t));}
int checked_int(std::size_t value,const char*error){if(value>static_cast<std::size_t>((std::numeric_limits<int>::max)()))throw std::runtime_error(error);return static_cast<int>(value);}
