std::wstring widen(std::string_view s){if(s.empty())return{};const int source_size=checked_int(s.size(),"utf8_too_large");const int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),source_size,nullptr,0);if(n<=0)throw std::runtime_error("utf8_invalid");std::wstring w(static_cast<std::size_t>(n),L'\0');if(MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),source_size,w.data(),n)!=n)throw std::runtime_error("utf8_conversion_failed");return w;}
