 void commit_owner_approval(std::string_view id,std::string_view canonical)override{if(persisted_approvals_.contains(std::string(id)))throw std::runtime_error("owner_approval_replay");append("APPROVAL\t"+std::string(id)+"\t"+std::string(canonical));persisted_approvals_[std::string(id)]=std::string(canonical);}
 void commit_authorization(std::string_view nonce,std::string_view grant,std::uint64_t use,std::string_view permit,std::string_view audit,std::string_view digest)override{append("USE\t"+std::string(grant)+"\t"+std::to_string(use)+"\t"+std::string(nonce));append("PERMIT\t"+std::string(permit));append_audit(audit);append("AUDIT\t"+std::string(digest));nonces_.insert(std::string(nonce));uses_[std::string(grant)]=use;permits_.insert(std::string(permit));audit_head_=digest;}
 void commit_outcome(std::string_view permit,std::string_view canonical,std::string_view digest)override{if(!permits_.contains(std::string(permit)))throw std::runtime_error("outcome_unknown_permit");append_audit(canonical);append("AUDIT\t"+std::string(digest));audit_head_=digest;}
 std::uint64_t service_generation()const override{return generation_;}
 void begin_behavior_session(std::string_view id,std::string_view binding)override{if(behavior_start_.contains(std::string(id)))throw std::runtime_error("behavior_session_replay");append("BEHAVIOR_BEGIN\t"+std::string(id)+"\t"+std::to_string(generation_)+"\t"+std::string(binding));behavior_start_[std::string(id)]={generation_,std::string(binding)};}
 void record_behavior_event(std::string_view id,std::string_view event,std::string_view evidence)override{if(!behavior_start_.contains(std::string(id))||!kp::valid_identifier(event)||!kp::valid_hex64(evidence))throw std::runtime_error("behavior_event_invalid");auto&events=behavior_events_[std::string(id)];if(events.contains(std::string(event))){if(events[std::string(event)]!=evidence)throw std::runtime_error("behavior_event_conflict");return;}append("BEHAVIOR_EVENT\t"+std::string(id)+"\t"+std::string(event)+"\t"+std::string(evidence));events[std::string(event)]=std::string(evidence);}
 kp::json::value behavior_session(std::string_view id)const override{auto it=behavior_start_.find(std::string(id));if(it==behavior_start_.end())throw std::runtime_error("behavior_session_missing");kp::json::value::array rows;auto events=behavior_events_.find(std::string(id));if(events!=behavior_events_.end())for(const auto&[event,digest]:events->second)rows.emplace_back(kp::json::value::object{{"event",kp::json::value(event)},{"evidenceSha256",kp::json::value(digest)}});return kp::json::value(kp::json::value::object{{"behaviorSessionId",kp::json::value(std::string(id))},{"startGeneration",kp::json::value(static_cast<std::int64_t>(it->second.first))},{"currentGeneration",kp::json::value(static_cast<std::int64_t>(generation_))},{"exactRunBindingSha256",kp::json::value(it->second.second)},{"events",kp::json::value(rows)}});}
 private:std::filesystem::path state_,audit_,rev_,approvals_;win_handle file_;std::unordered_set<std::string>nonces_,permits_;std::unordered_map<std::string,std::uint64_t>uses_;std::unordered_map<std::string,std::string>persisted_approvals_;mutable std::uint64_t epoch_=0;mutable std::unordered_set<std::string>revoked_;std::string audit_head_=std::string(64,'0');std::uint64_t generation_=0;std::unordered_map<std::string,std::pair<std::uint64_t,std::string>>behavior_start_;std::unordered_map<std::string,std::map<std::string,std::string>>behavior_events_;
 void load(){SetFilePointer(file_.h,0,nullptr,FILE_BEGIN);std::string all;std::array<char,4096>b{};DWORD n=0;while(ReadFile(file_.h,b.data(),checked_dword(b.size(),"state_read_buffer_too_large"),&n,nullptr)&&n)all.append(b.data(),n);std::istringstream in(all);std::string line;while(std::getline(in,line)){std::vector<std::string>f;std::size_t p=0;while(true){auto q=line.find('\t',p);f.push_back(line.substr(p,q==std::string::npos?q:q-p));if(q==std::string::npos)break;p=q+1;}if(f.size()==4&&f[0]=="USE"){uses_[f[1]]=std::stoull(f[2]);nonces_.insert(f[3]);}else if(f.size()==2&&f[0]=="PERMIT")permits_.insert(f[1]);else if(f.size()==2&&f[0]=="AUDIT")audit_head_=f[1];else if(f.size()==3&&f[0]=="APPROVAL")persisted_approvals_[f[1]]=f[2];else if(f.size()==2&&f[0]=="GENERATION")generation_=std::max<std::uint64_t>(generation_,std::stoull(f[1]));else if(f.size()==4&&f[0]=="BEHAVIOR_BEGIN"&&kp::valid_hex64(f[3]))behavior_start_[f[1]]={std::stoull(f[2]),f[3]};else if(f.size()==4&&f[0]=="BEHAVIOR_EVENT"&&kp::valid_hex64(f[3]))behavior_events_[f[1]][f[2]]=f[3];}}
 void load_rev()const{auto v=kp::json::parse(kp::read_text_file(rev_));const auto&o=v.as_object();epoch_=static_cast<std::uint64_t>(kp::json::required_int(o,"revocationEpoch"));revoked_.clear();for(const auto&x:kp::json::required_array(o,"revokedCapabilities"))if(x.is_string())revoked_.insert(x.as_string());}
 void append(const std::string&line){SetFilePointer(file_.h,0,nullptr,FILE_END);auto row=line+"\n";DWORD n=0;if(!WriteFile(file_.h,row.data(),checked_dword(row.size(),"state_row_too_large"),&n,nullptr)||static_cast<std::size_t>(n)!=row.size()||!FlushFileBuffers(file_.h))throw std::runtime_error("state_persist_failed");}
