int wmain(int argc,wchar_t**argv)try{if(argc==2&&std::wstring(argv[1])==L"--source-self-test"){std::cout<<"{\"status\":\"passed\",\"platform\":\"windows\",\"authorityCore\":\"v2\",\"completionEligible\":false}\n";return 0;}if(argc>=2&&std::wstring(argv[1])==L"--provision-key"){if(argc!=3)throw std::runtime_error("key_name_required");return provision_key(argv[2]);}if(argc>=2&&std::wstring(argv[1])==L"--store-lsa-secret-stdin"){if(argc!=3)throw std::runtime_error("secret_name_required");auto secret=read_secret_hex_stdin();try{lsa_store(argv[2],secret);}catch(...){SecureZeroMemory(secret.data(),secret.size()*sizeof(wchar_t));throw;}SecureZeroMemory(secret.data(),secret.size()*sizeof(wchar_t));return 0;}if(argc>=2&&std::wstring(argv[1])==L"--console"){if(argc!=3)throw std::runtime_error("config_path_required");g_stop_event=CreateEventW(nullptr,TRUE,FALSE,nullptr);auto c=load_config(argv[2]);serve(c);return 0;}if(argc>=2&&std::wstring(argv[1])==L"--service-config"){if(argc!=3)throw std::runtime_error("config_path_required");g_service_config=argv[2];}SERVICE_TABLE_ENTRYW table[]={{const_cast<LPWSTR>(L"KristinP1Authority"),service_main},{nullptr,nullptr}};if(!StartServiceCtrlDispatcherW(table))throw std::runtime_error("service_dispatcher_failed");return 0;}catch(const std::exception&e){std::cerr<<"P1A Windows authority fatal: "<<e.what()<<"\n";return 1;}
